/* eslint-disable react/prop-types */
import React, { useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Avatar,
  Button,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  MenuItem,
  Popover,
} from '@mui/material';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import { axios } from '../../utils/axios';
// components
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { IMAGE_URL } from '../../utils/config';
import { updateUrlParams } from '../../utils/urlUtilis';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

export default function ListPrivilegesCategory() {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [opens, setOpens] = useState();
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [privilegeCategory, setPrivilegeCategory] = React.useState([]);
  const [search, setsearch] = useState('');
  const [totalCount, setTotalCount] = useState(0);
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const queryPrms = new URLSearchParams(location.search);
  const id = queryPrms.get("id")
  const catid = id
  const [delId, setDelId] = useState(0);
  const [searchParams, setSearchParams] = useSearchParams();
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  const fetchData = async () => {
    try {
      // let url = `module/admin/privilege/${catid}?_page=${page}&_limit=${rowsPerPage}`;
      let url = `module/admin/privilegeCategory?_page=${page}&_limit=${rowsPerPage}&privilegeId=${catid}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });
      const res = await axios.get(url);
      if (res.status === 200) {
        setPrivilegeCategory(res.data.data.privilegeCategory);
        console.log(privilegeCategory)
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);    // { path: 'editprivilegedata/:privilegeId', nodeRef: createRef(), element: <Editprivilegedata /> },
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };
  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    // debugger
    const getPrivilegeItems = (ids, data) => {
      // debugger
      const id = searchParams.get("id") // url?id=some value
      navigate(`/dashboard/privilegeitems?id=${ids}&privilegeId=${id}`, { state: { types: "Privilege Category", process: "Add" } });
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => getPrivilegeItems(value, original)}>
            <Iconify icon={'carbon:view'} title={"View Privilege Data"} sx={{ mr: 2 }} /> View
          </MenuItem>
          <MenuItem onClick={() => handleformdata(value, original?.name, original?.description)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.LISTINGPAGE?.CREATED_NAME || 'Created Name',
      id: "name",
      accessorKey: "name",
      showFilter: false,
      cell: ({ row }) => <span>{row?.original?.name || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.DESCRIPTION || 'Description',
      id: "description",
      accessorKey: "description",
      cell: ({ row }) => <span>{row?.original?.description || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.CREATED_AT || 'Created At',
      id: "createdAt",
      accessorKey: "createdAt",
      cell: ({ row }) => <span>{DateFormat(row?.original?.createdAt) || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.UPDATED_AT || 'Updated At',
      id: "updatedAt",
      accessorKey: "updatedAt",
      cell: ({ row }) => <span>{DateFormat(row?.original?.updatedAt) || '---'}</span>,
    },
    {
      header: i18?.SETTINGSLIST?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent,
    },
  ]

  // const columns = useMemo(() => COLUMNS, []);
  // const data = React.useMemo(() => privilegeCategory.map((category) => {
  //   return {
  //     // icon: user?.icon,
  //     name: category?.name,
  //     description: category?.description,
  //     createdAt: category?.createdAt,
  //     updatedAt: category?.updatedAt,
  //     action: category?._id,
  //   };
  // }), [privilegeCategory]);

  if (!location && !location?.state)
    return null
  const { cate } = location?.state || { cate: '' };
  const handleformdata = async (ids, cat, des) => {
    const type = 'Privilege Category';
    const action = 'Edit';

    navigate(`/dashboard/editprivilegedata/${ids}`, {
      state: { process: action, types: type, id: ids, categories: cat, catid, descs: des, cate },
    });
  };

  const deleteModal = (ids) => {
    // sessionStorage.setItem("userId", ids);
    setDelId(ids)
    setOpens(true);
  }

  const deletePrivilege = async () => {
    const ids = `${delId}`
    try {
      const res = await axios.delete(`module/admin/privilegeCategory/${ids}`);
      if (res.status === 200) {
        setOpens(false)
        GenerateToastConfig(res.data.message, 'error');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message, "error");
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = privilegeCategory.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'Privilege Category';
    const action = 'Add';
    const id = catid;
    // debugger
    navigate('/dashboard/addprivilege', { state: { types: type, process: action, ids: id, categories: cate } });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value);
  };

  const backtouser = () => {
    navigate('/dashboard/privilegecategory')
  }

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };


  return (
    <>
      <Helmet>
        <title> {`List Privilege Category | Admin panel`} </title>
      </Helmet>

      {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.LISTINGPAGE?.LIST_PRIVILEGE_CATEGORY || "List Privilege Category"}
        </Typography>
        <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
          {i18?.LISTINGPAGE?.ADD_PRIVILEGE_CATEGORYS || "Add Privilege Category"}
        </Button>
      </Stack>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Stack direction='row' alignItems="center">
          <Typography variant="h4" gutterBottom>
            {i18?.LISTINGPAGE?.LIST_PRIVILEGE_CATEGORY || "List Privilege Category"}
          </Typography>
        </Stack>

        <Stack direction='row' alignItems="center">
          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
            {i18?.LISTINGPAGE?.ADD_PRIVILEGE_CATEGORYS || "Add Privilege Category"}
          </Button>
        </Stack>

      </Stack>}

      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          {isMobile && <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />}
        </div>
        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={privilegeCategory}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>


        <DeleteModal
          isDeleteOpen={opens}
          handleClose={() => setOpens(false)}
          handleDelete={deletePrivilege}
        />

      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
      <GoBackButton
        style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}
        label={i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
        onClick={() => backtouser()}
        icon="icon-park-twotone:back"
      />
    </>
  );
}


